Assets/Game/Scripts/UI/ProductMenuContro:
using System;
using System.Collections.Generic;
using System.Linq;
using ShorelineDefense.Building;
using ShorelineDefense.Core;
using ShorelineDefense.Persistence;
using UnityEngine;
using UnityEngine.SceneManagement;
using UnityEngine.UIElements;

namespace ShorelineDefense.UI
{
    /// <summary>UI observes services; simulation and persistence remain in their owners.</summary>
    [DefaultExecutionOrder(1100), RequireComponent(typeof(UIDocument))]
    public sealed class ProductMenuController : MonoBehaviour
    {
        [SerializeField] private bool mainMenu;
        [SerializeField] private StyleSheet menuStyle;
        [SerializeField] private Font pixelFont;
        [SerializeField] private ShorelineDefense.Defenses.DefenseDefinition[] defenseCatalog;
        [SerializeField] private ShorelineDefense.Grid.BattlefieldDefinition battlefield;
        [SerializeField] private ShorelineDefense.Waves.EndlessEventSettings eventCatalog;
        [SerializeField] private ShorelineDefense.Grid.MapCatalog maps;
        private ShorelineDefense.Grid.MapDefinition selectedMap;
        public void ConfigureMaps(ShorelineDefense.Grid.MapCatalog catalog) => maps = catalog;
        private SaveGameService Saves => new SaveGameService(LocalGameData.Files, d => {
            var map = maps?.Find(d.saveVersion == 1 ? ShorelineDefense.Grid.MapCatalog.OriginalId : d.mapId);
            return (maps == null || map != null) && RunSaveCompatibility.Valid(d, defenseCatalog, map != null ? map.battlefield : battlefield, eventCatalog);
        });
        public static string Notice;
        public bool ModalOpen => overlay != null && overlay.style.display != DisplayStyle.None;
        public bool IsLoading => loading;
        public string CurrentPage => page;
        public event Action<string> PageChanged;
        public event Action ResearchPurchased;
        private VisualElement root, overlay, card, content;
        private Label feedback;
        private GameSpeedController speed;
        private RunSession session;
        private GameStateController game;
        private PlacementController placement;
        private StructureSelection selection;
        private string page;
        private Action cancelDialog;
        private bool loading;
        public void Configure(bool menu, StyleSheet style, Font font) { mainMenu = menu; menuStyle = style; pixelFont = font; }
        public void ConfigureCatalog(ShorelineDefense.Defenses.DefenseDefinition[] defenses, ShorelineDefense.Grid.BattlefieldDefinition map, ShorelineDefense.Waves.EndlessEventSettings events)
        { defenseCatalog = defenses; battlefield = map; eventCatalog = events; }
        private void Start()
        {
            root = GetComponent<UIDocument>().rootVisualElement;
            if (menuStyle != null) root.styleSheets.Add(menuStyle);
            if (pixelFont != null) root.style.unityFontDefinition = FontDefinition.FromFont(pixelFont);
            overlay = new VisualElement { name = "product-overlay" }; overlay.AddToClassList("product-overlay");
            card = new VisualElement { name = "product-card" }; card.AddToClassList("product-card");
            var scroll = new ScrollView(ScrollViewMode.Vertical); scroll.AddToClassList("product-scroll");
            content = scroll.contentContainer; content.name = "product-content"; card.Add(scroll); overlay.Add(card); root.Add(overlay);
            feedback = new Label { name = "save-feedback", pickingMode = PickingMode.Ignore }; feedback.AddToClassList("save-feedback"); root.Add(feedback);
            SettingsService.Instance.Apply();
            if (mainMenu) ShowMain();
            else
            {
                speed = FindFirstObjectByType<GameSpeedController>(); session = FindFirstObjectByType<RunSession>(); game = FindFirstObjectByType<GameStateController>();
                placement = FindFirstObjectByType<PlacementController>(); selection = FindFirstObjectByType<StructureSelection>();
                speed.Changed += SpeedChanged; game.StateChanged += StateChanged; session.FeedbackChanged += FeedbackChanged;
                Hide(); FeedbackChanged();
            }
            gameObject.AddComponent<RuntimeTooltips>();
            gameObject.AddComponent<ShorelineDefense.Tutorial.TutorialRuntime>();
        }
        private void OnDestroy()
        { if (speed != null) speed.Changed -= SpeedChanged; if (game != null) game.StateChanged -= StateChanged; if (session != null) session.FeedbackChanged -= FeedbackChanged; }
        private void FeedbackChanged() { if (feedback != null) feedback.text = session.Feedback; }
        private void Page(string title, string id)
        {
            card.EnableInClassList("research-card", id == "research");
            page = id; content.Clear(); cancelDialog = null; overlay.style.display = DisplayStyle.Flex; overlay.BringToFront();
            var heading = new Label(title); heading.AddToClassList("product-title"); content.Add(heading);
            PageChanged?.Invoke(id);
        }
        private void Copy(string text) { var label = new Label(text); label.AddToClassList("product-copy"); content.Add(label); }
        private Button ActionButton(string id, string text, Action action)
        { var button = new Button(action) { name = id, text = text }; button.AddToClassList("product-button"); content.Add(button); return button; }
        public void ShowMain()
        {
            Page("BORDER DEFENDERS", "main"); Copy("DANUBE QUARANTINE LINE\nHold the river. Defend the border.");
            var saves = Saves;
            bool valid = saves.Load(out _, out string error);
            ActionButton("menu-continue", "CONTINUE", Continue).SetEnabled(valid);
            ActionButton("menu-new", "NEW GAME", NewGame);
            ActionButton("menu-research", "RESEARCH", ShowResearch);
            ActionButton("menu-history", "RUN HISTORY", ShowHistory);
            ActionButton("menu-settings", "SETTINGS", ShowSettings);
            ActionButton("menu-quit", "QUIT", () => Confirm("QUIT GAME?", "Your last Preparation save will be kept.", "QUIT", Application.Quit, ShowMain));
            if (Notice != null) { Copy(Notice); Notice = null; }
            else if (error != null) Copy(valid ? error : "The active save could not be loaded. You can start a new run.");
            if (LocalGameData.Profile.Error != null) Copy("RESEARCH PROFILE: " + LocalGameData.Profile.Error);
        }
        public void ShowResearch()
        {
            if (!mainMenu || loading) return;
            Page("QUARANTINE RESEARCH PROGRAM", "research");
            var catalog = ShorelineDefense.Progression.ResearchCatalog.Load();
            if (catalog == null) Copy("Research catalog unavailable.");
            else content.Add(new ResearchTreeView(catalog, LocalGameData.Profile, () => mainMenu && !loading && page == "research", () => ResearchPurchased?.Invoke()));
            ActionButton("research-back", "BACK TO MAIN MENU", ShowMain);
        }
        public void NewGame()
        {
            ShowMapSelect();
        }
        public void ShowMapSelect()
        {
            Page("CHOOSE MAP", "maps"); selectedMap = null;
            if (maps == null) { Copy("Map catalog unavailable."); ActionButton("maps-back", "BACK", Back); return; }
            foreach (var map in maps.maps)
            {
                if (map == null) continue;
                if (map.preview != null) { var image = new Image { sprite = map.preview, scaleMode = ScaleMode.ScaleToFit }; image.style.height = 140; content.Add(image); }
                Copy(map.displayName + "\n" + map.description + "\n" + map.gameplayStyle + "\nPERSONAL BEST / WAVE " + LocalGameData.Profile.BestWave(map.id));
                ActionButton("map-" + map.id, "SELECT " + map.displayName, () => {
                    selectedMap = map;
                    Page(map.displayName, "map-confirm"); Copy(map.description + "\n" + map.gameplayStyle);
                    ActionButton("map-start", "START", ConfirmNew); ActionButton("maps-back", "BACK", ShowMapSelect);
                });
            }
            ActionButton("maps-back", "BACK", Back);
        }
        private void ConfirmNew()
        {
            if (Saves.Load(out _, out _))
                Confirm("START NEW RUN?", "Your current active run will be replaced. Completed run history will be kept.", "START NEW RUN", StartNew, Back);
            else StartNew();
        }
        private void StartNew()
        {
            var map = selectedMap ?? maps?.Find(session != null ? session.MapId : ShorelineDefense.Grid.MapCatalog.OriginalId);
            if (map == null) { Copy("Map unavailable."); return; }
            if (!Saves.Delete(out string error)) { Copy("Could not replace active save: " + error); return; }
            RunSession.Pending = null;
            Load(map.sceneName);
        }
        public void Continue()
        {
            if (!Saves.Load(out var data, out _)) { ShowMain(); return; }
            var map = maps?.Find(data.saveVersion == 1 ? ShorelineDefense.Grid.MapCatalog.OriginalId : data.mapId);
            if (map == null) { Copy("Saved map unavailable. Save preserved."); return; }
            RunSession.Pending = data; Load(map.sceneName);
        }
        private void Load(string scene)
        { if (loading) return; loading = true; Time.timeScale = 1; Page("LOADING...", "loading"); SceneManager.LoadSceneAsync(scene); }
        private void Hide() { overlay.style.display = DisplayStyle.None; page = null; PageChanged?.Invoke(null); }
        private void Back() { if (mainMenu) ShowMain(); else ShowPause(); }
        public void ShowPause()
        {
            if (game == null || !game.IsPlaying) return;
            if (speed.Speed != GameSpeed.Pause) speed.SetSpeed(GameSpeed.Pause);
            Page("PAUSED", "pause");
            Copy("Progress is saved between waves.\n" + (session.CanSave ? "Preparation progress can be saved now." : "Leaving now returns to the last Preparation save."));
            ActionButton("pause-resume", "RESUME", () => { Hide(); speed.Resume(); });
            ActionButton("pause-settings", "SETTINGS", ShowSettings);
            ActionButton("pause-restart", "RESTART RUN", () => Confirm("RESTART RUN?", "The current active run will be replaced.", "RESTART", StartNew, ShowPause));
            ActionButton("pause-main", "MAIN MENU", ReturnToMenu);
        }
        public void ReturnToMenu()
        {
            if (game.CurrentState == GameState.GameOver) { if (session.FinalizeRun()) Load("MainMenu"); else Copy(session.Feedback); return; }
            if (session.CanSave) { if (session.SaveNow()) Load("MainMenu"); else Copy("Progress could not be saved. Resume to try again."); }
            else Confirm("PROGRESS IS SAVED BETWEEN WAVES", "Current wave progress will be lost. Continue will return to your last Preparation save.", "QUIT CURRENT WAVE", () => Load("MainMenu"), ShowPause);
        }
        public void Confirm(string title, string message, string accept, Action yes, Action no)
        {
            Page(title, "confirm"); Copy(message); cancelDialog = no;
            ActionButton("confirm-cancel", "CANCEL", no); ActionButton("confirm-accept", accept, yes);
        }
        public void ShowHistory()
        {
            Page("RUN HISTORY", "history");
            var history = new RunHistoryService(LocalGameData.Files); var data = history.Load();
            Copy(data.runs.Count == 0 ? "No completed runs yet." : "PERSONAL BEST — WAVE " + data.runs.Max(r => r.wave));
            if (maps != null) foreach (var map in maps.maps) if (map != null) Copy(map.displayName + " / BEST WAVE " + LocalGameData.Profile.BestWave(map.id));
            foreach (var r in data.runs)
            {
                string date = DateTime.TryParse(r.endedUtc, out var ended) ? ended.ToLocalTime().ToString("yyyy-MM-dd HH:mm") : "Unknown date";
                Copy($"{maps?.Find(r.mapId)?.displayName ?? "DANUBE BORDER"}\n{date}\nWave {r.wave}  /  Kills {r.kills:N0}\nHomicides {r.homicides:N0}  /  Bosses {r.bosses:N0}\nEarned {r.earned:N0} RSD  /  {FormatDuration(r.duration)}" + (r.hasResearchReward ? $"\nRESEARCH EARNED +{r.researchEarned} RP" : ""));
            }
            if (history.Error != null) Copy("Some run history could not be loaded: " + history.Error);
            ActionButton("history-back", "BACK", Back);
        }
        public static string FormatDuration(double seconds) => TimeSpan.FromSeconds(seconds).ToString(seconds >= 3600 ? @"h\:mm\:ss" : @"mm\:ss");
        public void ShowSettings()
        {
            Page("SETTINGS", "settings"); var current = SettingsService.Instance.Current;
            var resolutions = new List<Vector2Int>();
            foreach (var r in Screen.resolutions) if (r.width >= 800 && r.height >= 600 && !resolutions.Contains(new Vector2Int(r.width, r.height))) resolutions.Add(new Vector2Int(r.width, r.height));
            if (!resolutions.Contains(new Vector2Int(current.width, current.height))) resolutions.Add(new Vector2Int(current.width, current.height));
            resolutions.Sort((a, b) => a.x != b.x ? a.x.CompareTo(b.x) : a.y.CompareTo(b.y));
            var resolution = new DropdownField("Resolution", resolutions.Select(r => r.x + " x " + r.y).ToList(), resolutions.IndexOf(new Vector2Int(current.width, current.height))) { name = "settings-resolution" }; content.Add(resolution);
            var fullscreen = new Toggle("Fullscreen") { name = "settings-fullscreen", value = current.fullscreen }; content.Add(fullscreen);
            var vsync = new Toggle("VSync") { name = "settings-vsync", value = current.vsync }; content.Add(vsync);
            var density = new DropdownField("VFX density", new List<string> { "Low", "Medium", "High" }, current.vfxDensity) { name = "settings-vfx" }; content.Add(density);
            var rewards = new Toggle("Show RSD reward popups") { name = "settings-rewards", value = current.rewardPopups }; content.Add(rewards);
            Copy("VFX density limits secondary effects and blood decals.\nGameplay damage and enemy counts stay the same.");
            if (Application.isEditor) Copy("Display mode applies in the standalone game. Editor Game View is controlled separately.");
            var result = new Label { name = "settings-result" }; result.AddToClassList("product-copy"); content.Add(result);
            var tutorial = new Toggle("Tutorial ON / OFF") { name = "settings-tutorial", value = LocalGameData.Tutorial.Enabled }; content.Add(tutorial);
            tutorial.RegisterValueChangedCallback(e => {
                if (!LocalGameData.Tutorial.SetEnabled(e.newValue)) { tutorial.SetValueWithoutNotify(LocalGameData.Tutorial.Enabled); result.text = LocalGameData.Tutorial.Error; }
            });
            ActionButton("settings-reset-tutorial", "RESET TUTORIAL PROGRESS", () => Confirm("RESET TUTORIAL PROGRESS?", "Reset tutorial lessons only. Research, RP, Run History and settings are kept.", "RESET TUTORIAL", () => {
                bool ok = LocalGameData.Tutorial.ResetProgress(); ShowSettings();
                if (!ok) Copy(LocalGameData.Tutorial.Error);
            }, ShowSettings));
            if (LocalGameData.Tutorial.Error != null) Copy("TUTORIAL PROFILE: " + LocalGameData.Tutorial.Error);
            ActionButton("settings-apply", "APPLY & SAVE", () => {
                var size = resolutions[resolution.index];
                bool ok = SettingsService.Instance.Save(new GameSettings { width = size.x, height = size.y, fullscreen = fullscreen.value, vsync = vsync.value, vfxDensity = density.index, rewardPopups = rewards.value });
                result.text = ok ? "SETTINGS SAVED" : "Settings could not be saved: " + SettingsService.Instance.Error;
            });
            ActionButton("settings-back", "BACK", Back);
        }
        private void SpeedChanged()
        { if (game.IsPlaying && speed.Speed == GameSpeed.Pause && !ModalOpen) ShowPause(); else if (speed.Speed != GameSpeed.Pause && page == "pause") Hide(); }
        private void StateChanged(GameState state)
        {
            if (state != GameState.GameOver) return;
            Page("RUN COMPLETE", "over");
            var stats = FindFirstObjectByType<RunStatistics>();
            Copy(maps?.Find(session.MapId)?.displayName ?? "DANUBE BORDER");
            Copy($"WAVE REACHED {stats.HighestWaveReached}\nTOTAL KILLS {stats.TotalKills:N0}\nHOMICIDES {stats.Homicides:N0}\nBOSSES KILLED {stats.BossesKilled:N0}\nRSD EARNED {stats.TotalMoneyEarned:N0}\nSTRUCTURES BUILT {stats.StructuresBuilt}\nDURATION {FormatDuration(session.Duration)}");
            var earned = new Label { name = "run-research-earned" }; earned.AddToClassList("research-balance"); content.Add(earned);
            void RewardText() {
                var award = session.ResearchAward;
                earned.text = award == null ? "RESEARCH SAVE PENDING\n" + session.Feedback : $"RESEARCH EARNED  +{award.Total} RP\nTOTAL RP  {LocalGameData.Profile.ResearchPoints:N0}\n" + $"Waves {award.waveRP} / Bosses {award.bossRP} / Quality {award.qualityRP} / Milestones {award.milestoneRP}";
            }
            RewardText();
            if (session.ResearchAward == null) ActionButton("over-retry", "RETRY SAVE", () => { session.FinalizeRun(); RewardText(); });
            // Existing game-over label remains for legacy scene/tests; product overlay owns this view.
            root.Q<Label>("game-over").style.visibility = Visibility.Hidden;
            ActionButton("over-new", "NEW RUN", () => { if (session.FinalizeRun()) ShowMapSelect(); else Copy(session.Feedback); });
            ActionButton("over-main", "MAIN MENU", ReturnToMenu);
        }
        private void Update()
        {
            if (loading || root == null) return;
            if (mainMenu) { if (Input.GetKeyDown(KeyCode.Escape)) { if (page == "confirm") cancelDialog?.Invoke(); else if (page != "main") ShowMain(); } return; }
            if (game == null || !game.IsPlaying) return;
            if (Input.GetKeyDown(KeyCode.Escape))
            {
                if (placement.IsInteracting) placement.Cancel();
                else if (page == "confirm") cancelDialog?.Invoke();
                else if (page == "settings" || page == "history") Back();
                else if (page == "pause") { Hide(); speed.Resume(); }
                else if (selection.Selected != null) selection.Clear();
                else ShowPause();
                return;
            }
            if (Input.GetKeyDown(KeyCode.Space) && !ShorelineDefense.Tutorial.TutorialView.ConsumesSpace && (page == null || page == "pause"))
            { if (speed.Speed == GameSpeed.Pause) { Hide(); speed.Resume(); } else ShowPause(); }
            if (ModalOpen) return;
            var buttons = root.Q("defense-buttons");
            if (buttons != null) for (int i = 0; i < 8; i++)
                if (Input.GetKeyDown(KeyCode.Alpha1 + i)) { var b = buttons.Children().OfType<Button>().ElementAtOrDefault(i); if (b != null && b.enabledSelf) using (var e = NavigationSubmitEvent.GetPooled()) { e.target = b; b.SendEvent(e); } }
            if (Input.GetKeyDown(KeyCode.Delete) && selection.Selected != null)
            {
                var selected = selection.Selected; var builder = selected.Owner;
                speed.SetSpeed(GameSpeed.Pause);
                Confirm("DISMANTLE STRUCTURE?", $"Refund: {builder.RefundFor(selected):N0} RSD", "DISMANTLE", () => { builder.TryDismantle(selected, out _); Hide(); speed.Resume(); }, () => { Hide(); speed.Resume(); });
            }
        }
    }
}

Assets/Game/Scripts/UI/PrototypeHud.cs:
using ShorelineDefense.Base;
using ShorelineDefense.Core;
using UnityEngine;
using UnityEngine.UIElements;

namespace ShorelineDefense.UI
{
    [RequireComponent(typeof(UIDocument))]
    public sealed class PrototypeHud : MonoBehaviour
    {
        [SerializeField] private BaseHealth playerBase;
        [SerializeField] private GameStateController game;
        [SerializeField] private BorderBreachService border;
        [SerializeField] private RunStatistics statistics;
        private Label healthLabel;
        private Label gameOverLabel;
        private bool subscribed;
        public string HealthText => healthLabel?.text;
        public bool GameOverVisible => gameOverLabel != null && gameOverLabel.style.display.value == DisplayStyle.Flex;

        public void Configure(BaseHealth target, GameStateController state) { playerBase = target; game = state; }
        public void ConfigureLegacy() { border = null; RefreshHealth(); }

        private void OnEnable()
        {
            if (playerBase == null || game == null) return;
            var root = GetComponent<UIDocument>().rootVisualElement;
            healthLabel = root.Q<Label>("base-hp");
            gameOverLabel = root.Q<Label>("game-over");
            if (healthLabel == null || gameOverLabel == null)
            {
                Debug.LogError("Prototype HUD needs its UXML with base-hp and game-over labels.", this);
                return;
            }
            playerBase.Changed += RefreshHealth;
            if (statistics != null) statistics.OnHomicidesChanged += OnHomicides;
            game.StateChanged += RefreshState;
            subscribed = true;
            RefreshHealth();
            RefreshState(game.CurrentState);
        }

        private void OnDisable()
        {
            if (!subscribed) return;
            playerBase.Changed -= RefreshHealth;
            if (statistics != null) statistics.OnHomicidesChanged -= OnHomicides;
            game.StateChanged -= RefreshState;
            subscribed = false;
        }

        private void OnHomicides(long count) => RefreshHealth();
        private void RefreshHealth() => healthLabel.text = border != null && statistics != null ?
            $"HOMICIDES {statistics.Homicides:N0}" + (border.MaxHomicides > 0 ? $" / {border.MaxHomicides:N0}" : "") :
            $"BASE HP: {playerBase.CurrentHealth} / {playerBase.MaxHealth}";
        private void RefreshState(GameState state)
        {
            gameOverLabel.style.display = state == GameState.GameOver ? DisplayStyle.Flex : DisplayStyle.None;
            if (state == GameState.GameOver && statistics != null) gameOverLabel.text = statistics.Report;
        }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using ShorelineDefense.Progression;
using UnityEngine;
using UnityEngine.UIElements;

namespace ShorelineDefense.UI
{
    /// <summary>Presentation-only board. The service validates every transaction and saves immediately.</summary>
    public sealed class ResearchTreeView : VisualElement
    {
        private readonly ResearchCatalog catalog;
        private readonly PlayerProfileService profile;
        private readonly ResearchTreeService tree;
        private readonly Label balance, detailTitle, detailCopy, result;
        private readonly Image detailIcon;
        private readonly Button purchase;
        private readonly Dictionary<ResearchNodeDefinition, Button> buttons = new Dictionary<ResearchNodeDefinition, Button>();
        private readonly List<ResearchBranchBoard> boards = new List<ResearchBranchBoard>();
        private ResearchNodeDefinition selected;
        private readonly Action onPurchased;
        public ResearchTreeView(ResearchCatalog definitions, PlayerProfileService player, Func<bool> betweenRuns, Action purchased = null)
        {
            onPurchased = purchased;
            catalog = definitions; profile = player; tree = new ResearchTreeService(player, definitions, betweenRuns);
            name = "research-tree";
            var header = new VisualElement(); header.AddToClassList("research-balance-row"); Add(header);
            if (catalog?.researchPointIcon != null) { var icon = new Image { sprite = catalog.researchPointIcon }; icon.AddToClassList("research-rp-icon"); header.Add(icon); }
            balance = new Label { name = "research-balance" }; balance.AddToClassList("research-balance"); header.Add(balance);
            var note = new Label("Applies to new runs. Continue keeps its original research."); note.AddToClassList("research-note"); Add(note);
            var body = new VisualElement(); body.AddToClassList("research-body"); Add(body);
            var branches = new VisualElement { name = "research-branches" }; branches.AddToClassList("research-branches"); body.Add(branches);
            foreach (ResearchBranch branch in Enum.GetValues(typeof(ResearchBranch)))
            {
                var column = new VisualElement(); column.AddToClassList("research-column"); branches.Add(column);
                var title = new Label(branch == ResearchBranch.Weapons ? "WEAPONS" : branch.ToString().ToUpperInvariant()); title.AddToClassList("research-branch-title"); column.Add(title);
                title.tooltip = ShorelineDefense.Tutorial.TutorialCatalog.BranchHint(branch.ToString());
                var board = new ResearchBranchBoard(definitions.nodes.Where(n => n.branch == branch).ToArray(), n => tree.Status(n));
                boards.Add(board); column.Add(board);
                foreach (var node in board.Nodes)
                {
                    var n = node;
                    var button = new Button(() => Select(n)) { name = "research-node-" + n.id };
                    button.AddToClassList("research-node");
                    button.style.position = Position.Absolute; button.style.width = 86; button.style.height = 86;
                    button.style.left = new Length(n.boardPosition.x * 100, LengthUnit.Percent); button.style.marginLeft = -43;
                    button.style.top = n.boardPosition.y;
                    var icon = new Image { sprite = n.icon, pickingMode = PickingMode.Ignore }; icon.AddToClassList("research-node-icon"); button.Add(icon);
                    var label = new Label(n.displayName.ToUpperInvariant()) { pickingMode = PickingMode.Ignore }; label.AddToClassList("research-node-name"); button.Add(label);
                    var state = new Label { name = "node-state", pickingMode = PickingMode.Ignore }; state.AddToClassList("research-node-state"); button.Add(state);
                    button.tooltip = n.displayName.ToUpperInvariant() + "\n" + n.description + "\n" + n.costRP + " RP\nRequires: " + Requirements(n);
                    board.Add(button); buttons[n] = button;
                }
            }
            var detail = new VisualElement { name = "research-detail" }; detail.AddToClassList("research-detail"); body.Add(detail);
            detailIcon = new Image(); detailIcon.AddToClassList("research-detail-icon"); detail.Add(detailIcon);
            detailTitle = new Label(); detailTitle.AddToClassList("research-detail-title"); detail.Add(detailTitle);
            detailCopy = new Label(); detailCopy.AddToClassList("research-detail-copy"); detail.Add(detailCopy);
            purchase = new Button(Purchase) { name = "research-purchase" }; purchase.AddToClassList("product-button"); detail.Add(purchase);
            result = new Label { name = "research-result" }; result.AddToClassList("research-detail-copy"); detail.Add(result);
            selected = definitions.nodes.FirstOrDefault(); Refresh();
        }
        private static string Requirements(ResearchNodeDefinition node) => node.prerequisites.Length == 0 ? "None" : string.Join(" + ", node.prerequisites.Select(n => n.displayName));
        private void Select(ResearchNodeDefinition node) { selected = node; result.text = ""; Refresh(); }
        private void Purchase()
        {
            if (selected == null) return;
            string name = selected.displayName;
            bool ok = tree.TryPurchase(selected.id, out string error);
            Refresh(); result.text = ok ? "RESEARCH COMPLETE\n" + name + "\nApplies to new runs." : error;
            if (ok) onPurchased?.Invoke();
        }
        public void Refresh()
        {
            balance.text = $"AVAILABLE  {profile.ResearchPoints:N0} RP";
            foreach (var pair in buttons)
            {
                var state = tree.Status(pair.Key); var b = pair.Value;
                b.EnableInClassList("node-locked", state == ResearchNodeStatus.Locked);
                b.EnableInClassList("node-purchased", state == ResearchNodeStatus.Purchased);
                b.EnableInClassList("node-insufficient", state == ResearchNodeStatus.InsufficientRP);
                b.EnableInClassList("node-selected", pair.Key == selected);
                b.Q<Label>("node-state").text = state == ResearchNodeStatus.Purchased ? "[OK] RESEARCHED" : state == ResearchNodeStatus.Locked ? "[X] LOCKED" : state == ResearchNodeStatus.InsufficientRP ? pair.Key.costRP + " RP / NEED RP" : pair.Key.costRP + " RP / READY";
            }
            foreach (var b in boards) b.MarkDirtyRepaint();
            if (selected == null) return;
            var status = tree.Status(selected);
            detailIcon.sprite = selected.icon; detailTitle.text = selected.displayName.ToUpperInvariant();
            detailCopy.text = selected.branch.ToString().ToUpperInvariant() + " / TIER " + selected.tier + "\n\nPERMANENT EFFECT\n" + selected.description + "\n\nCOST  " + selected.costRP + " RP\n\nREQUIRES\n" + Requirements(selected) + "\n\n" +
                (status == ResearchNodeStatus.Locked ? "Missing prerequisite research." : status == ResearchNodeStatus.InsufficientRP ? "Insufficient RP. Complete runs to earn research." : status == ResearchNodeStatus.Purchased ? "Permanently researched." : "Available for research.");
            purchase.text = status == ResearchNodeStatus.Purchased ? "RESEARCHED" : "RESEARCH / " + selected.costRP + " RP";
            purchase.SetEnabled(profile.Available && status == ResearchNodeStatus.Available);
            if (profile.Error != null) result.text = profile.Error;
        }
    }
    internal sealed class ResearchBranchBoard : VisualElement
    {
        public ResearchNodeDefinition[] Nodes { get; }
        public ResearchBranchBoard(ResearchNodeDefinition[] nodes, Func<ResearchNodeDefinition, ResearchNodeStatus> status)
        {
            Nodes = nodes; AddToClassList("research-branch-board");
            generateVisualContent += context => {
                var painter = context.painter2D; float w = contentRect.width;
                // Low-contrast technical grid, then dependency elbows. Node children render above it.
                painter.lineWidth = 1; painter.strokeColor = new Color(.15f, .25f, .26f, .45f);
                for (float y = 0; y < contentRect.height; y += 20) { painter.BeginPath(); painter.MoveTo(new Vector2(0, y)); painter.LineTo(new Vector2(w, y)); painter.Stroke(); }
                foreach (var node in nodes) foreach (var parent in node.prerequisites)
                {
                    if (!nodes.Contains(parent)) continue;
                    var from = new Vector2(parent.boardPosition.x * w, parent.boardPosition.y + 86);
                    var to = new Vector2(node.boardPosition.x * w, node.boardPosition.y);
                    float mid = (from.y + to.y) * .5f;
                    painter.lineWidth = 2; painter.strokeColor = status(parent) == ResearchNodeStatus.Purchased ? new Color(.48f, .75f, .7f) : new Color(.28f, .4f, .42f);
                    painter.BeginPath(); painter.MoveTo(from); painter.LineTo(new Vector2(from.x, mid)); painter.LineTo(new Vector2(to.x, mid)); painter.LineTo(to); painter.Stroke();
                }
            };
        }
    }
}

Assets/Game/Scripts/UI/RuntimeTooltips.c:
using UnityEngine;
using UnityEngine.UIElements;

namespace ShorelineDefense.UI
{
    /// <summary>UI Toolkit's editor tooltip property is rendered explicitly for the Player.</summary>
    public sealed class RuntimeTooltips : MonoBehaviour
    {
        private VisualElement root, target;
        private Label tooltip;
        private void Start()
        {
            root = GetComponent<UIDocument>().rootVisualElement;
            tooltip = new Label { name = "runtime-tooltip", pickingMode = PickingMode.Ignore };
            tooltip.AddToClassList("runtime-tooltip"); tooltip.style.display = DisplayStyle.None; root.Add(tooltip);
            root.RegisterCallback<PointerOverEvent>(Over); root.RegisterCallback<PointerOutEvent>(Out);
        }
        private void Over(PointerOverEvent e)
        {
            target = e.target as VisualElement;
            while (target != null && string.IsNullOrEmpty(target.tooltip)) target = target.parent;
            if (target == null) { tooltip.style.display = DisplayStyle.None; return; }
            tooltip.text = target.tooltip; tooltip.style.display = DisplayStyle.Flex; tooltip.BringToFront();
            float width = root.resolvedStyle.width, height = root.resolvedStyle.height;
            tooltip.style.left = Mathf.Clamp(target.worldBound.xMin, 12, Mathf.Max(12, width - 370));
            tooltip.style.top = Mathf.Clamp(target.worldBound.yMin - 160, 12, Mathf.Max(12, height - 170));
        }
        private void Out(PointerOutEvent e) { target = null; tooltip.style.display = DisplayStyle.None; }
        private void LateUpdate()
        {
            if (target == null || tooltip == null) return;
            // Menu navigation can detach a hovered tree without delivering PointerOut.
            if (target.panel != root.panel) { target = null; tooltip.style.display = DisplayStyle.None; }
            else tooltip.text = target.tooltip;
        }
        private void OnDestroy() { root?.UnregisterCallback<PointerOverEvent>(Over); root?.UnregisterCallback<PointerOutEvent>(Out); tooltip?.RemoveFromHierarchy(); }
    }
}

